import { AccountSession } from '../game/account-session.js';
import { toggleAchievements } from '../game/achievements.js';
import { AudioSettings } from '../game/audio-settings.js';
import { resetGame } from '../game/game-over.js';
import { state } from '../game/game-state.js';
import { toggleShop } from '../game/shop.js';
import { setAudioSetting, toggleAudio } from './audio.js';
import { authFormBusy, becomeGuest, closeProfileMenu, openAuth, submitAuth } from './auth.js';
import { toggleDifficulty } from './difficulty.js';
import { toggleLanguageMenu } from './language.js';
import { downloadNewspaper, shareNewspaper } from './newspaper.js';
import { resign, selectMode, toggleModes } from './modes.js';
import { resolveSaveSync, saveSyncBusy, showSaveSync, updateSaveSyncUI } from './save-sync.js';
import { renderGuestStats, toggleGuestStats } from './ui.js';

function initializeControls() {
    if (document.getElementById('newspaper-section')) {
        document.getElementById('btn-share-result').addEventListener('click', shareNewspaper);
        document.getElementById('btn-download-newspaper').addEventListener('click', downloadNewspaper);
    }
    document.getElementById('btn-achievements').addEventListener('click', event => { toggleAchievements(true); });
    document.getElementById('btn-audio').addEventListener('click', event => { toggleAudio(); });
    document.getElementById('lang-toggle').addEventListener('click', event => { toggleLanguageMenu(); });
    document.getElementById('btn-shop').addEventListener('click', event => { toggleShop(true); });
    document.getElementById('btn-login').addEventListener('click', event => { closeProfileMenu(); openAuth('login'); });
    document.getElementById('btn-register').addEventListener('click', event => { closeProfileMenu(); openAuth('register'); });
    document.getElementById('btn-become-guest').addEventListener('click', event => { closeProfileMenu(); becomeGuest(); });
    document.getElementById('btn-difficulty').addEventListener('click', event => { toggleDifficulty(true); });
    document.getElementById('btn-mode').addEventListener('click', event => { toggleModes(true); });
    document.getElementById('btn-auth-continue').addEventListener('click', event => { AccountSession.activity(); });
    document.getElementById('auth-dialog').addEventListener('cancel', event => { if (authFormBusy) event.preventDefault(); });
    document.getElementById('auth-form').addEventListener('submit', event => { submitAuth(event); });
    document.getElementById('auth-cancel').addEventListener('click', event => { document.getElementById('auth-dialog').close(); });
    document.getElementById('auth-invite-yes').addEventListener('click', event => { openAuth('register'); });
    document.getElementById('auth-invite-no').addEventListener('click', event => { document.getElementById('auth-invite').close(); });
    document.getElementById('save-sync-review').addEventListener('click', event => { showSaveSync(); });
    document.getElementById('save-sync-dialog').addEventListener('cancel', event => { if (saveSyncBusy) event.preventDefault(); });
    document.getElementById('save-sync-dialog').addEventListener('close', event => { updateSaveSyncUI(); });
    document.getElementById('save-sync-local').addEventListener('click', event => { resolveSaveSync('local'); });
    document.getElementById('save-sync-cloud').addEventListener('click', event => { resolveSaveSync('cloud'); });
    document.getElementById('save-sync-confirm').addEventListener('click', event => { resolveSaveSync(); });
    document.getElementById('save-sync-cancel').addEventListener('click', event => { document.getElementById('save-sync-dialog').close(); });
    document.getElementById('daily-reminder').addEventListener('click', event => { selectMode('daily'); });
    document.getElementById('btn-resign').addEventListener('click', event => { resign(); });
    document.getElementById('btn-end-mode').addEventListener('click', event => { toggleModes(true); });
    document.getElementById('btn-end-difficulty').addEventListener('click', event => { toggleDifficulty(true); });
    document.getElementById('btn-restart').addEventListener('click', event => { resetGame(state.difficulty); });
    document.getElementById('audio-modal').addEventListener('click', event => { if (event.target === event.currentTarget) toggleAudio(false); });
    document.getElementById('audio-dismiss').addEventListener('click', event => { toggleAudio(false); });
    document.getElementById('audio-music-toggle').addEventListener('click', event => { setAudioSetting('musicEnabled', !AudioSettings.get().musicEnabled); });
    document.getElementById('audio-music-volume').addEventListener('input', event => { setAudioSetting('musicVolume', event.currentTarget.valueAsNumber); });
    document.getElementById('audio-sfx-toggle').addEventListener('click', event => { setAudioSetting('sfxEnabled', !AudioSettings.get().sfxEnabled); });
    document.getElementById('audio-sfx-volume').addEventListener('input', event => { setAudioSetting('sfxVolume', event.currentTarget.valueAsNumber); });
    document.getElementById('audio-close').addEventListener('click', event => { toggleAudio(false); });
    document.getElementById('difficulty-modal').addEventListener('click', event => { if (event.target === event.currentTarget) toggleDifficulty(false); });
    document.getElementById('difficulty-dismiss').addEventListener('click', event => { toggleDifficulty(false); });
    document.getElementById('mode-modal').addEventListener('click', event => { if (event.target === event.currentTarget) toggleModes(false); });
    document.getElementById('mode-dismiss').addEventListener('click', event => { toggleModes(false); });
    document.getElementById('shop-modal').addEventListener('click', event => { if (event.target === event.currentTarget) toggleShop(false); });
    document.getElementById('shop-dismiss-btn').addEventListener('click', event => { toggleShop(false); });
    document.getElementById('shop-close-btn').addEventListener('click', event => { toggleShop(false); });
    document.getElementById('achievements-modal').addEventListener('click', event => { if (event.target === event.currentTarget) toggleAchievements(false); });
    document.getElementById('achievements-dismiss-btn').addEventListener('click', event => { toggleAchievements(false); });
    document.getElementById('btn-guest-stats').addEventListener('click', event => { toggleGuestStats(true); });
    document.getElementById('guest-stats-modal').addEventListener('click', event => { if (event.target === event.currentTarget) toggleGuestStats(false); });
    document.getElementById('guest-stats-dismiss-btn').addEventListener('click', event => { toggleGuestStats(false); });
    document.getElementById('stats-mode').addEventListener('change', event => { renderGuestStats(); });
    document.getElementById('guest-stats-close-btn').addEventListener('click', event => { toggleGuestStats(false); });
}

export { initializeControls };
